'use strict';

/**
* Parse a JSON Pointer string into an array of reference tokens.
*
* @module @stdlib/utils-json-pointer-parse
*
* @example
* var parse = require( '@stdlib/utils-json-pointer-parse' );
*
* var tokens = parse( '/foo/bar' );
* // returns [ 'foo', 'bar' ]
*
* tokens = parse( '/a~1b/c~0d' );
* // returns [ 'a/b', 'c~d' ]
*
* tokens = parse( '' );
* // returns []
*/

// MODULES //

var main = require( './main.js' );


// EXPORTS //

module.exports = main;
